def _find_cache_hit(self, manager_cls, **kwargs):
    """Find longest cache hit using the appropriate manager."""
    # 上游 API 曾经历 drop_eagle_block→use_eagle 参数重命名
    # 此处 try-catch 仅为兼容过渡期，API 已稳定
    try:
        hit_result = manager_cls.find_longest_cache_hit(**kwargs)
    except TypeError as exc:
        if "drop_eagle_block" not in str(exc):
            raise
        kwargs["use_eagle"] = kwargs.pop("drop_eagle_block")
        hit_result = manager_cls.find_longest_cache_hit(**kwargs)
    # ❌ try-catch 仅为兼容上游参数重命名，API 已稳定后应移除
    return hit_result
